import sys,random,time,networkx as nx
sys.path.insert(0,'/workspace/submission')
from compiler import _Gen, PlanFailure
random.seed(777)
for n in list(range(2,15))+[16,20,24,32]:
 maxrec=0; maxsplits=0
 for it in range(100 if n<20 else 20):
  # random participant tree and packing records
  records=[]
  roots={i:0 for i in range(n)}
  numtrees=random.randint(1,min(3*n,100))
  for k in range(numtrees):
   # random undirected tree
   T=[]
   for v in range(1,n):
    u=random.randrange(v);T.append((u,v))
   root=random.randrange(n)
   # choose weight from small list
   w=random.choice([1,2,3,5,10,random.randint(1,10**6)])
   # orient tree away root
   adj={i:[] for i in range(n)}
   for a,b in T:adj[a].append(b);adj[b].append(a)
   st=[root];seen={root};oriented=[]
   while st:
    x=st.pop()
    for y in adj[x]:
     if y not in seen:seen.add(y);oriented.append((x,y));st.append(y)
   records.append((root,w,oriented));roots[root]+=w
  # Build H capacities aggregate
  H=nx.DiGraph();H.add_nodes_from(range(n));loads={}
  for r,w,es in records:
   for e in es:loads[e]=loads.get(e,0)+w
  for (a,b),c in loads.items():H.add_edge(a,b,capacity=c)
  # gen
  try:
   Ts,Cs=_Gen(H,list(range(n)),roots).generate()
  except Exception as e:
   print('FAIL',n,it,'trees',numtrees,'D',sum(roots.values()),repr(e));raise
  # verify loads capacity/root
  agg={}
  for key,T in Ts.items():
   for e in T:agg[e]=agg.get(e,0)+Cs[key]
  for e,c in agg.items(): assert c<=H[e[0]][e[1]]['capacity'],(e,c,H[e[0]][e[1]])
  for u,c in roots.items(): assert sum(v for (r,i),v in Cs.items() if r==u)==c
  maxrec=max(maxrec,len(Ts))
 print('n',n,'max records',maxrec,flush=True)
print('OK')
